3	import org.springframework.jdbc.core.JdbcTemplate;
4	import org.springframework.stereotype.Repository;
5	
6	/**
7	 * 跑道咨询锁：例行开始与紧急接报事务先对同一跑道行加行锁串行化，
8	 * 保证“批准/开始 vs 紧急接报”得到唯一占用状态；不同跑道为不同行，互不阻塞。
9	 */
10	@Repository
11	public class RunwayLockRepository {
12	
13	    private final JdbcTemplate jdbc;
14	
15	    public RunwayLockRepository(JdbcTemplate jdbc) {
16	        this.jdbc = jdbc;
17	    }
18	
19	    /**
20	     * 确保跑道锁行存在并对其加排他行锁（FOR UPDATE）。必须在事务内调用，锁持有到事务提交/回滚。
21	     */
