3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.List;
7	
8	/**
9	 * 结构化幂等指纹：对各字段做长度前缀编码，并显式编码集合规模与元素结构，
10	 * 使合法文本包含分隔符（如 "|"、","）时仍无歧义。
11	 *
12	 * <p>编码规则：标量 = UTF-8 字节长度 + ":" + 文本；集合 = 元素个数 + "#" + 各元素顺序拼接。
13	 * 例如 ["a|b","c"] 与 ["a","b|c"] 编码不同。最终对完整编码取 SHA-256 十六进制。</p>
14	 */
15	public final class StructuredFingerprint {
16	
17	    private StructuredFingerprint() {
18	    }
19	
20	    /** 计算标量序列的结构化指纹。 */
21	    public static String sha256(String scope, String... scalarFields) {
22	        StringBuilder builder = new StringBuilder();
23	        appendField(builder, scope);
24	        for (String field : scalarFields) {
25	            appendField(builder, field == null ? "" : field);
26	        }
27	        return digest(builder.toString());
28	    }
29	
30	    /**
31	     * 计算“标量头 + 单个集合（集合元素为多个标量字段）”的结构化指纹。
32	     *
33	     * @param scope        幂等作用域
34	     * @param scalarFields 标量头字段（顺序固定）
35	     * @param collection   集合；每个元素为一组顺序固定的标量字段
36	     */
37	    public static String sha256WithCollection(String scope, List<String> scalarFields,
38	                                              List<List<String>> collection) {
39	        StringBuilder builder = new StringBuilder();
40	        appendField(builder, scope);
41	        for (String field : scalarFields) {
42	            appendField(builder, field == null ? "" : field);
43	        }
44	        builder.append(collection.size()).append('#');
45	        for (List<String> element : collection) {
46	            for (String field : element) {
47	                appendField(builder, field == null ? "" : field);
48	            }
49	        }
50	        return digest(builder.toString());
51	    }
52	
53	    private static void appendField(StringBuilder builder, String value) {
54	        byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
55	        builder.append(bytes.length).append(':').append(value);
