341	                "RWM2", T0, T0.plus(Duration.ofHours(2)), 60, 2)));
342	        assertDoesNotThrow(() -> routineService.publishPlan(new PlanPublishRequest("idem-fail",
343	                "RWM2", T0.plus(Duration.ofHours(2)), T0.plus(Duration.ofHours(4)), 60, 2)));
344	        Integer idemFailRows = jdbc.queryForObject(
345	                "SELECT COUNT(*) FROM idempotency_record WHERE request_id = 'idem-fail'", Integer.class);
346	        assertEquals(1, idemFailRows, "失败不占键，仅成功后有一条幂等记录");
347	    }
