349	    /**
350	     * 结构化指纹无歧义：朴素 "|" 拼接会碰撞的两组集合，结构化编码指纹不同，同键异参判409。
351	     * 集合A：单项 [code="x", text="a|b"]；集合B：两项 [code="x",text="a"]、[code="b",text="z"]。
352	     */
353	    @Test
