368	    /** 并发日历发布：相同 expectedVersion 仅一个成功产生新版本，其余409。 */
369	    @Test
370	    void concurrentCalendarPublishesOnlyOneSucceeds() throws Exception {
371	        int threads = 6;
372	        ExecutorService pool = Executors.newFixedThreadPool(threads);
373	        CountDownLatch ready = new CountDownLatch(threads);
374	        CountDownLatch start = new CountDownLatch(1);
375	        AtomicInteger success = new AtomicInteger();
376	        AtomicInteger conflict = new AtomicInteger();
377	        List<Future<?>> futures = new java.util.ArrayList<>();
378	        for (int i = 0; i < threads; i++) {
379	            final int idx = i;
380	            futures.add(pool.submit(() -> {
381	                ready.countDown();
382	                start.await();
383	                try {
384	                    routineService.publishCalendar(new CalendarPublishRequest("cc-cal-" + idx, 1,
385	                            T0.plusSeconds(idx), List.of()));
