402	        pool.shutdown();
403	        assertEquals(1, success.get());
404	        assertEquals(threads - 1, conflict.get());
405	        assertEquals(2, jdbc.queryForObject("SELECT MAX(version) FROM flight_calendar", Integer.class));
406	        assertEquals(2, jdbc.queryForObject("SELECT COUNT(*) FROM flight_calendar", Integer.class));
