410	     * 并发：例行开始 与 紧急接报 同跑道竞争唯一占用。
411	     * 任一先后，最终都满足：紧急事件进行中且计划为终态（取消或中止），不存在“巡检进行中且紧急关闭进行中”。
412	     */
413	    @Test
414	    void concurrentStartAndEmergencyYieldUniqueOccupancy() throws Exception {
415	        PlanResponse plan = publishPlan("cc-occ", "RWO", T0, T0.plus(Duration.ofHours(2)), 60, 1);
416	        int pairs = 8;
417	        ExecutorService pool = Executors.newFixedThreadPool(pairs * 2);
418	        CountDownLatch ready = new CountDownLatch(pairs * 2);
