441	                    // 同跑道仅一个进行中紧急事件，其余 RUNWAY_ACTIVE_EVENT_EXISTS 合法
442	                }
443	                return null;
444	            }));
445	        }
446	        ready.await(5, TimeUnit.SECONDS);
447	        start.countDown();
448	        for (Future<?> f : futures) {
