package com.example.starter.runway;

import java.time.Instant;

/**
 * 受控跑道登记：正整数米长度；存在活动施工后不许缩改。
 *
 * @param runwayId     跑道编号（合成数据）
 * @param lengthMeters 跑道长度（单位：米，正整数）
 * @param version      聚合乐观锁版本：登记为1，每次成功修改加1
 * @param requestId    登记幂等请求标识
 * @param createdAt    记录创建时间（UTC）
 * @param updatedAt    记录最近更新时间（UTC）
 */
public record ControlledRunway(
        String runwayId,
        int lengthMeters,
        int version,
        String requestId,
        Instant createdAt,
        Instant updatedAt) {
}

package com.example.starter.runway;

/**
 * 施工单状态：DRAFT未生效 / EFFECTIVE已生效 / COMPLETED已结束 / WITHDRAWN已撤回（终态）。
 */
public enum ConstructionOrderStatus {
    /** 未生效：可修改段、可撤回；不产生闭锁。 */
    DRAFT,
    /** 已生效：冻结区间并阻断整跑道新使用；不得删除或缩段。 */
    EFFECTIVE,
    /** 已结束：全部施工段验收完成（终态）。 */
    COMPLETED,
    /** 已撤回：仅未生效单可撤回（终态）。 */
    WITHDRAWN;

    /** 是否终态（结束或撤回，不再变更）。 */
    public boolean isTerminal() {
        return this == COMPLETED || this == WITHDRAWN;
    }
}

package com.example.starter.runway;

/**
 * 施工段状态：PENDING未生效 / LOCKED闭锁中 / CLEARED已验收解除。
 */
public enum ConstructionSegmentStatus {
    /** 未生效：施工单尚未生效，不产生闭锁。 */
    PENDING,
    /** 闭锁中：施工单已生效，该段计入活动施工区间并集。 */
    LOCKED,
    /** 已验收解除：两个不同验收人凭据齐全，本段闭锁消除。 */
    CLEARED
}

